public sealed class PlusPackTests
{
 string folder; GameClient c; bool background;
 void Independent(Scene scene,LoadSceneMode mode){if(scene.name=="GameClient")scene.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<GameClient>(true)).Single().SaveFolderOverride=folder;}
 [UnitySetUp] public IEnumerator Setup(){background=Application.runInBackground;Application.runInBackground=true;Time.timeScale=1;folder=Path.Combine(Application.temporaryCachePath,"PlusPack-"+Guid.NewGuid().ToString("N"));SceneManager.sceneLoaded+=Independent;yield return SceneManager.LoadSceneAsync("GameClient");yield return ClientStartupWait.Ready();c=GameClient.Instance;ForestRuntimeAcceptance.IsGaming=false;c.DailyLogin.Close();c.Tutorial.SetCleared();}
 [UnityTearDown] public IEnumerator Cleanup(){Time.timeScale=1;c?.LocalStore.Cancel();c?.RewardedAds.Cancel();yield return SceneManager.LoadSceneAsync("TargetPreview");SceneManager.sceneLoaded-=Independent;if(Directory.Exists(folder))Directory.Delete(folder,true);Application.runInBackground=background;}
 IEnumerator Purchase(string id){Assert.That(c.LocalStore.Request(id),Is.True,id);yield return null;yield return null;Assert.That(c.LocalStore.Model.Recorded(id),Is.True);}
 void Capture(string name)=>ScreenCapture.CaptureScreenshot(Path.GetFullPath(Path.Combine(Application.dataPath,"../../../reverse/com.Chodun.CatGunner/1.1.61-vc257/reports/visual/plus-consumers-"+name+"-gpu.png")));
 [UnityTest] public IEnumerator PurchasedTimePackDoublesNextForestRound(){yield return Purchase("catgunner_pluspack_0");c.Restart();Assert.That(c.Forest.GameTime_Now,Is.EqualTo(360));Assert.That(c.RoundTimeMax,Is.EqualTo(360));c.LocalStore.Model.Now=()=>DateTime.UtcNow.AddDays(8);Assert.That(c.RoundTimeMax,Is.EqualTo(360));c.Restart();Assert.That(c.RoundTimeMax,Is.EqualTo(180));}
 [UnityTest] public IEnumerator SettlementBossNaturalWinKeepsMultipliedRewardAndPersists(){yield return Purchase("catgunner_pluspack_1");c.State.Owned_Gun_list[0]=20;Assert.That(c.Inventory.Equip(0,0),Is.True);int dia=c.State.Dia;c.BossMode.Game_Enter();float deadline=Time.realtimeSinceStartup+25;while(!c.BossMode.GameWin_UI.activeInHierarchy&&Time.realtimeSinceStartup<deadline)yield return null;Assert.That(c.BossMode.GameWin_UI.activeInHierarchy,Is.True);Assert.That(c.State.Dia-dia,Is.EqualTo(300));Assert.That(c.BossMode.Reward_txt.text,Is.EqualTo("300"));Assert.That(c.BossMode.Bonus_txt.text,Is.EqualTo("900"));Assert.That(new SaveArchive(folder).Load().Dia,Is.EqualTo(c.State.Dia));yield return new WaitForSeconds(.8f);Capture("boss-reward");yield return null;c.BossMode.Game_Win();Assert.That(c.State.Dia-dia,Is.EqualTo(300));c.LocalStore.Model.Now=()=>DateTime.UtcNow.AddDays(8);c.BossMode.Bonus_AD_Show();yield return null;yield return null;Assert.That(c.State.Dia-dia,Is.EqualTo(900));c.BossMode.Bonus_AD_Show();yield return null;Assert.That(c.State.Dia-dia,Is.EqualTo(900));}
 [UnityTest] public IEnumerator TimePackRunsBossFor120Seconds(){yield return Purchase("catgunner_pluspack_0");c.BossMode.Game_Enter();float deadline=Time.realtimeSinceStartup+8;while(!c.BossMode.Playing&&Time.realtimeSinceStartup<deadline)yield return null;Assert.That(c.BossMode.Playing,Is.True);Assert.That(c.BossMode.RoundTimeMax,Is.EqualTo(120));Assert.That(c.BossMode.GameTime_Now,Is.InRange(118,120));Capture("boss-time");yield return null;}
 [UnityTest] public IEnumerator SettlementMineRuns78SecondsAndTruncatesReward(){yield return Purchase("catgunner_pluspack_0");yield return Purchase("catgunner_pluspack_1");c.MineMode.Game_Enter();float deadline=Time.realtimeSinceStartup+10;while(!c.MineMode.Playing&&Time.realtimeSinceStartup<deadline)yield return null;Assert.That(c.MineMode.Playing,Is.True);Assert.That(c.MineMode.RoundTimeMax,Is.EqualTo(78).Within(.00001));Assert.That(c.MineMode.GameTime_Now,Is.InRange(76,78));int dia=c.State.Dia;c.MineMode.Dia_Score=39;c.MineMode.Game_End();Assert.That(c.MineMode.Reward_Value,Is.EqualTo(4));Assert.That(c.MineMode.Best_Reward,Is.EqualTo(3));Assert.That(c.State.Dia-dia,Is.EqualTo(4));yield return new WaitForSeconds(.8f);Capture("mine-reward");yield return null;c.MineMode.Game_End();Assert.That(c.State.Dia-dia,Is.EqualTo(4));c.LocalStore.Model.Now=()=>DateTime.UtcNow.AddDays(8);c.MineMode.Bonus_AD_Show();yield return null;yield return null;Assert.That(c.State.Dia-dia,Is.EqualTo(16));}
 [UnityTest] public IEnumerator TimePackRunsRaidFor70SecondsWithoutChangingRewardBands(){yield return Purchase("catgunner_pluspack_0");c.RaidMode.Panel_Open();c.RaidMode.Game_Enter_Normal();float deadline=Time.realtimeSinceStartup+8;while(!c.RaidMode.Playing&&Time.realtimeSinceStartup<deadline)yield return null;Assert.That(c.RaidMode.Playing,Is.True);Assert.That(c.RaidMode.GameTime_Max,Is.EqualTo(70));Assert.That(c.RaidMode.GameTime_Now,Is.InRange(68,70));Capture("raid-time");yield return null;}
 [UnityTest] public IEnumerator SettlementMonsterNaturalClearAndAdDoNotDuplicate(){yield return Purchase("catgunner_pluspack_1");c.State.Owned_Gun_list[0]=20;Assert.That(c.Inventory.Equip(0,0),Is.True);int coins=c.State.PetCoin;c.MonsterMode.Game_Enter();float deadline=Time.realtimeSinceStartup+70;while(c.MonsterMode.PetCoin_Accum==0&&(c.MonsterMode.Entering||c.MonsterMode.Playing)&&Time.realtimeSinceStartup<deadline)yield return null;Assert.That(c.MonsterMode.PetCoin_Accum,Is.GreaterThanOrEqualTo(60));c.MonsterMode.Game_GiveUp();int earned=c.MonsterMode.PetCoin_Accum;Assert.That(earned%60,Is.Zero);Assert.That(c.State.PetCoin-coins,Is.EqualTo(earned));Assert.That(c.MonsterMode.Reward_txt.text,Is.EqualTo(earned.ToString()));yield return new WaitForSeconds(.8f);Capture("monster-reward");yield return null;c.MonsterMode.Bonus_AD_Show();yield return null;yield return null;Assert.That(c.State.PetCoin-coins,Is.EqualTo(earned*2));c.MonsterMode.Bonus_AD_Show();yield return null;Assert.That(c.State.PetCoin-coins,Is.EqualTo(earned*2));}
 [UnityTest] public IEnumerator SevenOriginalItemsShowPurchasedStateCountdownAndExpireAfterColdReload(){yield return Purchase("catgunner_pluspack_0");yield return Purchase("catgunner_pluspack_1");yield return Purchase("catgunner_pluspack_2");yield return SceneManager.LoadSceneAsync("GameClient");yield return ClientStartupWait.Ready();c=GameClient.Instance;ForestRuntimeAcceptance.IsGaming=false;c.DailyLogin.Close();c.Tutorial.SetCleared();c.WeeklyShop.Open_Auto("hud");yield return new WaitForSeconds(.4f);var items=c.gameObject.scene.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<PlusPackItem>(true)).ToArray();Assert.That(items.Length,Is.EqualTo(7));foreach(var item in items){item.Reload();Assert.That(item.ActivePanel.activeSelf,Is.True);Assert.That(item.NonPurchasePanel.activeSelf,Is.False);Assert.That(item.RemainingText.text,Does.Contain("d"));}Capture("plus-active");yield return null;c.LocalStore.Model.Now=()=>DateTime.UtcNow.AddDays(8);c.LocalStore.RefreshPlusPresentation();foreach(var item in items){Assert.That(item.ActivePanel.activeSelf,Is.False);Assert.That(item.NonPurchasePanel.activeSelf,Is.True);Assert.That(item.RemainingText.text,Is.Empty);}Assert.That(AutoMergeAccess.EntitlementProvider(),Is.False);Assert.That(c.LocalStore.CanBuy("catgunner_pluspack_0"),Is.True);Assert.That(c.State.PurchaseHistory,Is.Empty);}
 [UnityTest] public IEnumerator OriginalPlusButtonRaycastPurchaseUpdatesPanelsAndSaves(){c.Forest.Stage_Value_Max=c.State.Stage_Value_Max=200;c.WeeklyShop.Open_Auto("hud");yield return new WaitForSeconds(.4f);var item=c.gameObject.scene.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<PlusPackItem>(true)).Single(i=>i.Type==0&&!i.IsBanner);var button=item.GetComponent<LocalPurchaseButton>().Button;var scroll=item.GetComponentInParent<ScrollRect>();Canvas.ForceUpdateCanvases();var viewport=scroll.viewport;float range=scroll.content.rect.height-viewport.rect.height;float delta=viewport.rect.center.y-viewport.InverseTransformPoint(item.transform.position).y;scroll.verticalNormalizedPosition=Mathf.Clamp01(scroll.verticalNormalizedPosition-delta/range);scroll.StopMovement();yield return new WaitForSeconds(.4f);yield return Click(button);Assert.That(c.PlusActive(0),Is.True);Assert.That(item.ActivePanel.activeSelf,Is.True);Assert.That(item.NonPurchasePanel.activeSelf,Is.False);Assert.That(new SaveArchive(folder).Load().SimulatedPurchases.Any(p=>p.productId=="catgunner_pluspack_0"),Is.True);Capture("plus-purchased");yield return null;}
 [UnityTest] public IEnumerator DisabledPurchaseVariantAndCanceledRequestCannotActivateAnyBenefits(){Assert.That(c.LocalStore.Request("catgunner_pluspack_0"),Is.True);c.LocalStore.Cancel();yield return null;Assert.That(c.PlusActive(0),Is.False);yield return Purchase("catgunner_pluspack_0");yield return Purchase("catgunner_pluspack_1");c.OfflinePurchaseSimulation=false;c.LocalStore.RefreshPlusPresentation();c.Restart();Assert.That(c.RoundTimeMax,Is.EqualTo(180));Assert.That(c.BossMode.GameTime_Max_return(),Is.EqualTo(60));Assert.That(c.MineMode.GameTime_Max_return(),Is.EqualTo(60));Assert.That(c.PlusReward(3,150),Is.EqualTo(150));Assert.That(c.LocalStore.Request("catgunner_pluspack_2"),Is.False);c.OfflinePurchaseSimulation=true;Assert.That(c.PlusActive(0),Is.True);Assert.That(c.PlusReward(3,150),Is.EqualTo(300));}
 static IEnumerator Click(Button button){Canvas.ForceUpdateCanvases();Assert.That(button.isActiveAndEnabled&&button.interactable,Is.True,button.name);var module=EventSystem.current.GetComponent<StandaloneInputModule>();var mouse=module.gameObject.AddComponent<ForestFeedbackMouseFixture>();module.inputOverride=mouse;try{var r=(RectTransform)button.transform;mouse.Position=RectTransformUtility.WorldToScreenPoint(null,r.TransformPoint(r.rect.center));var hits=new List<RaycastResult>();EventSystem.current.RaycastAll(new PointerEventData(EventSystem.current){position=mouse.Position},hits);Assert.That(hits.Count,Is.GreaterThan(0));Assert.That(hits[0].gameObject.GetComponentInParent<Button>(),Is.SameAs(button),"Top hit: "+hits[0].gameObject.name);yield return null;mouse.Down=mouse.Held=true;yield return null;mouse.Down=mouse.Held=false;mouse.Up=true;yield return null;mouse.Up=false;yield return null;}finally{module.inputOverride=null;UnityEngine.Object.Destroy(mouse);}}
}

public sealed class PlusPackRecoveryRulesTests
{
 [Test] public void NativeTimeFactorsKeepSpeedRunAndMonsterUnchanged(){Assert.That(LocalPurchases.PlusTimeLimit(0,180,true),Is.EqualTo(360));Assert.That(LocalPurchases.PlusTimeLimit(3,60,true),Is.EqualTo(120));Assert.That(LocalPurchases.PlusTimeLimit(2,60,true),Is.EqualTo(78).Within(.00001));Assert.That(LocalPurchases.PlusTimeLimit(5,60,true),Is.EqualTo(70));Assert.That(LocalPurchases.PlusTimeLimit(1,60,true),Is.EqualTo(60));Assert.That(LocalPurchases.PlusTimeLimit(4,60,true),Is.EqualTo(60));Assert.That(LocalPurchases.PlusTimeLimit(0,180,false),Is.EqualTo(180));}
 [Test] public void NativeRewardsKeepSpeedRunAndRaidUnchangedAndTruncateMine(){Assert.That(LocalPurchases.PlusReward(3,150,true),Is.EqualTo(300));Assert.That(LocalPurchases.PlusReward(4,30,true),Is.EqualTo(60));Assert.That(LocalPurchases.PlusReward(2,3,true),Is.EqualTo(4));Assert.That(LocalPurchases.PlusReward(2,4,true),Is.EqualTo(6));Assert.That(LocalPurchases.PlusReward(1,30,true),Is.EqualTo(30));Assert.That(LocalPurchases.PlusReward(5,25,true),Is.EqualTo(25));}
 [Test] public void SevenDayBoundaryLocalLedgerInvalidDatesAndDisabledVariantRemainSeparate(){var now=new DateTime(2026,10,11,0,0,0,DateTimeKind.Utc);var s=new SaveData{Gun_Collect=new bool[65],Selected_items=new[]{0,-1,-1},Upgrade_Lv=new int[3],PlusPack_Purchase_Dates=new[]{now.ToString("O"),"bad",null}};var guns=new GunInventory(s,(a,b)=>a);var missions=new Missions(s,ProgressionCatalogue.Load(),guns,()=>now);var model=new LocalPurchases(s,guns,missions,()=>now);Assert.That(model.PlusActive(0),Is.False);Assert.That(model.PlusRemaining(1),Is.EqualTo(TimeSpan.Zero));Assert.That(model.Apply("catgunner_pluspack_0"),Is.True);now=now.AddDays(7).AddTicks(-1);Assert.That(model.PlusActive(0),Is.True);Assert.That(model.PlusRemaining(0).Ticks,Is.EqualTo(1));now=now.AddTicks(1);Assert.That(model.PlusActive(0),Is.False);Assert.That(model.Apply("catgunner_pluspack_0"),Is.True);Assert.That(model.PlusRemaining(0),Is.EqualTo(TimeSpan.FromDays(7)));}
}
